<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Terms of Use</title>
    <style>
        :root {
            --primary-color: #2563eb;
            --primary-hover: #1d4ed8;
            --error-color: #dc2626;
            --text-color: #111827;
            --text-muted: #4b5563;
            --bg-color: #f3f4f6;
            --surface-color: #ffffff;
            --border-color: #6b7280;
            --focus-ring: #2563eb;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 1rem;
        }

        .container {
            background-color: var(--surface-color);
            padding: 2.5rem;
            border-radius: 0.75rem;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
            width: 100%;
            max-width: 26rem;
        }

        h1 {
            font-size: 1.5rem;
            font-weight: 600;
            margin-bottom: 1.5rem;
        }

        .form-field {
            margin-bottom: 2rem;
        }

        .checkbox-wrapper {
            display: flex;
            align-items: flex-start;
            gap: 0.75rem;
        }

        /* Custom Checkbox implementation */
        input[type="checkbox"] {
            appearance: none;
            background-color: var(--surface-color);
            margin: 0;
            font: inherit;
            color: currentColor;
            width: 1.25em;
            height: 1.25em;
            border: 2px solid var(--border-color);
            border-radius: 0.25rem;
            display: grid;
            place-content: center;
            cursor: pointer;
            flex-shrink: 0;
            margin-top: 0.125rem; /* align with first line of text */
        }

        input[type="checkbox"]::before {
            content: "";
            width: 0.65em;
            height: 0.65em;
            transform: scale(0);
            transition: 120ms transform ease-in-out;
            box-shadow: inset 1em 1em white;
            transform-origin: center;
            clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%);
        }

        input[type="checkbox"]:checked {
            background-color: var(--primary-color);
            border-color: var(--primary-color);
        }

        input[type="checkbox"]:checked::before {
            transform: scale(1);
        }

        input[type="checkbox"]:focus-visible {
            outline: 2px solid var(--focus-ring);
            outline-offset: 2px;
        }

        input[type="checkbox"][aria-invalid="true"] {
            border-color: var(--error-color);
            border-width: 2px;
        }

        label {
            font-size: 1rem;
            line-height: 1.5;
            cursor: pointer;
        }

        .required-marker {
            color: var(--error-color);
            margin-left: 0.25rem;
        }

        .help-text {
            font-size: 0.875rem;
            color: var(--text-muted);
            margin-left: 2rem;
            margin-top: 0.35rem;
        }

        .error-text {
            font-size: 0.875rem;
            color: var(--error-color);
            margin-left: 2rem;
            margin-top: 0.35rem;
            font-weight: 500;
        }

        .submit-btn {
            width: 100%;
            background-color: var(--primary-color);
            color: white;
            border: none;
            border-radius: 0.5rem;
            padding: 0.875rem 1rem;
            font-size: 1rem;
            font-weight: 500;
            cursor: pointer;
            transition: background-color 0.2s;
        }

        .submit-btn:hover {
            background-color: var(--primary-hover);
        }

        .submit-btn:focus-visible {
            outline: 2px solid var(--focus-ring);
            outline-offset: 2px;
        }

        @media (prefers-reduced-motion: reduce) {
            input[type="checkbox"]::before {
                transition: none;
            }
        }

        /* High contrast support */
        @media (forced-colors: active) {
            input[type="checkbox"] {
                border-color: CanvasText;
            }
            input[type="checkbox"]:checked {
                background-color: CanvasText;
            }
            input[type="checkbox"]::before {
                box-shadow: inset 1em 1em Canvas;
            }
            .submit-btn {
                border: 1px solid CanvasText;
            }
        }
    </style>
</head>
<body>
    <div id="root"></div>

    <!-- React and ReactDOM -->
    <script src="https://unpkg.com/react@18/umd/react.production.min.js" crossorigin></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js" crossorigin></script>
    <!-- Babel for in-browser JSX transpilation -->
    <script src="https://unpkg.com/babel-standalone@6/babel.min.js"></script>

    <script type="text/babel">
        const { useState, useRef } = React;

        function ConsentForm() {
            const [isChecked, setIsChecked] = useState(false);
            const [showError, setShowError] = useState(false);
            const checkboxRef = useRef(null);

            const handleSubmit = (e) => {
                e.preventDefault();
                if (!isChecked) {
                    setShowError(true);
                    if (checkboxRef.current) {
                        checkboxRef.current.focus();
                    }
                } else {
                    setShowError(false);
                    alert("Terms accepted successfully!");
                }
            };

            const handleChange = (e) => {
                setIsChecked(e.target.checked);
                if (e.target.checked && showError) {
                    setShowError(false);
                }
            };

            const ariaDescribedBy = `terms-help ${showError ? 'terms-error' : ''}`.trim();

            return (
                <main className="container">
                    <h1>Create your account</h1>
                    <form onSubmit={handleSubmit} noValidate>
                        <div className="form-field">
                            <div className="checkbox-wrapper">
                                <input
                                    type="checkbox"
                                    id="terms-consent"
                                    name="termsConsent"
                                    required
                                    checked={isChecked}
                                    onChange={handleChange}
                                    aria-describedby={ariaDescribedBy}
                                    aria-invalid={showError}
                                    ref={checkboxRef}
                                />
                                <label htmlFor="terms-consent">
                                    I agree to the Terms of Use <span aria-hidden="true" className="required-marker">*</span>
                                </label>
                            </div>
                            <p id="terms-help" className="help-text">
                                Read our terms carefully before agreeing.
                            </p>
                            {showError && (
                                <p id="terms-error" className="error-text">
                                    Error: You must agree to the terms to continue.
                                </p>
                            )}
                        </div>
                        <button type="submit" className="submit-btn">Accept and continue</button>
                    </form>
                </main>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<ConsentForm />);
    </script>
</body>
</html>
